(\forall_S yA)[x:=u]_S=
\begin{cases}
\forall_S yA,&y=x,\\
\forall_S y(A[x:=u]_S),&y\ne x\land y\notin\operatorname{SV}_{KM}(u),\\
\forall_S z((A[y:=\operatorname{svar}(z)]_S)[x:=u]_S),&y\ne x\land y\in\operatorname{SV}_{KM}(u),
\end{cases}

(\forall_C YA)[X:=U]_C=
\begin{cases}
\forall_C YA,&Y=X,\\
\forall_C Y(A[X:=U]_C),&Y\ne X\land Y\notin\operatorname{CV}_{KM}(U),\\
\forall_C Z((A[Y:=\operatorname{cvar}(Z)]_C)[X:=U]_C),&Y\ne X\land Y\in\operatorname{CV}_{KM}(U),
\end{cases}
